RSSDDCError rss_ddc_profile_store_export_json(const RSSDDCProfileStore*s,char*b,size_t cap,size_t*required){if(!s||!required)return RSS_DDC_ERROR_ARGUMENT;size_t n=0;emit(b,cap,&n,"{\"schemaVersion\":1,\"databaseVersion\":\"%s\",\"minimumRSSDDCVersion\":\"%s\",\"packId\":\"%s\",\"profiles\":[",s->has_info?s->info.database_version:"local-export",s->has_info?s->info.minimum_rss_ddc_version:"0.1.0",s->has_info?s->info.pack_id:"local-export");for(size_t i=0;i<s->profile_count;i++){const ProfileRecord*r=&s->profiles[i];emit(b,cap,&n,"%s{\"id\":\"%s\",\"identity\":{\"productName\":\"%s\",\"provider\":\"%s\",\"transport\":\"%s\",\"external\":%s",i?",":"",r->id,r->identity.product_name,rss_ddc_provider_string(r->identity.provider),r->identity.transport,r->identity.external?"true":"false");if(r->identity.manufacturer[0])emit(b,cap,&n,",\"manufacturer\":\"%s\"",r->identity.manufacturer);if(r->identity.serial[0])emit(b,cap,&n,",\"serial\":\"%s\"",r->identity.serial);if(r->identity.branch_device_id[0])emit(b,cap,&n,",\"branchDeviceId\":\"%s\"",r->identity.branch_device_id);emit(b,cap,&n,"},\"confidence\":\"%s\",\"controls\":[",rss_ddc_profile_confidence_name(r->confidence));for(size_t j=0;j<r->control_count;j++){const RSSDDCProfileControl*q=&r->controls[j];emit(b,cap,&n,"%s{\"id\":\"%s\",\"method\":\"%s\",\"address\":%u,\"readable\":%s,\"writable\":%s,\"confidence\":\"%s\",\"enums\":[",j?",":"",rss_ddc_profile_control_name(q->id),q->method==RSS_DDC_PROFILE_METHOD_VCP?"vcp":"lg-alt-input",q->address,q->readable?"true":"false",q->writable?"true":"false",rss_ddc_profile_confidence_name(q->confidence));for(size_t k=0;k<q->enum_value_count;k++)emit(b,cap,&n,"%s{\"id\":\"%s\",\"name\":\"%s\",\"value\":%u}",k?",":"",q->enum_values[k].id,q->enum_values[k].name,q->enum_values[k].raw_value);emit(b,cap,&n,"]}");}emit(b,cap,&n,"]}");}emit(b,cap,&n,"]}");*required=n+1;if(!b&&!cap)return RSS_DDC_OK;if(!b||cap<n+1)return RSS_DDC_ERROR_ARGUMENT;b[n]=0;return RSS_DDC_OK;}
RSSDDCError rss_ddc_profile_store_save_file(const RSSDDCProfileStore*s,const char*path){if(!s||!path||strlen(path)>RSS_DDC_PROFILE_PATH_MAX)return RSS_DDC_ERROR_ARGUMENT;size_t n=0;RSSDDCError z=rss_ddc_profile_store_export_json(s,NULL,0,&n);if(z)return z;char *d=malloc(n),*tmp=malloc(strlen(path)+12);if(!d||!tmp){free(d);free(tmp);return RSS_DDC_ERROR_SYSTEM;}z=rss_ddc_profile_store_export_json(s,d,n,&n);if(z){free(d);free(tmp);return z;}snprintf(tmp,strlen(path)+12,"%s.tmp.XXXXXX",path);int fd=mkstemp(tmp);if(fd<0){free(d);free(tmp);return RSS_DDC_ERROR_SYSTEM;}size_t off=0;while(off<n-1){ssize_t w=write(fd,d+off,n-1-off);if(w<=0){z=RSS_DDC_ERROR_SYSTEM;break;}off+=(size_t)w;}if(!z&&fsync(fd)!=0)z=RSS_DDC_ERROR_SYSTEM;if(close(fd)!=0&&!z)z=RSS_DDC_ERROR_SYSTEM;if(!z&&rename(tmp,path)!=0)z=RSS_DDC_ERROR_SYSTEM;if(z)unlink(tmp);free(d);free(tmp);return z;}

static bool match(const RSSDDCProfileIdentity *p, const RSSDDCProfileIdentity *a, unsigned *score) {
    if (p->provider != a->provider || p->external != a->external || strcmp(p->product_name, a->product_name) ||
        strcmp(p->transport, a->transport)) return false;
    unsigned n = 4;
    if (p->manufacturer[0]) { if (strcmp(p->manufacturer, a->manufacturer)) return false; ++n; }
    if (p->serial[0]) { if (strcmp(p->serial, a->serial)) return false; ++n; }
    if (p->branch_device_id[0]) { if (strcmp(p->branch_device_id, a->branch_device_id)) return false; ++n; }
    *score = n;
    return true;
}
static unsigned rank(RSSDDCProfileSource x){static const unsigned r[]={2,3,4,1};return (size_t)x<4?r[x]:0;}
static bool equal_control(const RSSDDCProfileControl*a,const RSSDDCProfileControl*b){return a->method==b->method&&a->address==b->address&&a->readable==b->readable&&a->writable==b->writable&&a->enum_value_count==b->enum_value_count&&!memcmp(a->enum_values,b->enum_values,a->enum_value_count*sizeof(a->enum_values[0]));}
RSSDDCError rss_ddc_profile_store_resolve(const RSSDDCProfileStore*s,const RSSDDCProfileIdentity*id,RSSDDCEffectiveProfile*out){if(!s||!id||!out)return RSS_DDC_ERROR_ARGUMENT;RSSDDCEffectiveProfile*r=calloc(1,sizeof(*r));if(!r)return RSS_DDC_ERROR_SYSTEM;r->identity=*id;unsigned co[RSS_DDC_PROFILE_MAX_CONTROLS]={},so[RSS_DDC_PROFILE_MAX_CONTROLS]={},sp[RSS_DDC_PROFILE_MAX_CONTROLS]={};RSSDDCError z=RSS_DDC_OK;for(size_t i=0;i<s->profile_count&&!z;i++){const ProfileRecord*p=&s->profiles[i];unsigned score;if(!match(&p->identity,id,&score))continue;for(size_t j=0;j<p->control_count;j++){const RSSDDCProfileControl*q=&p->controls[j];size_t k=0;while(k<r->control_count&&r->controls[k].id!=q->id)++k;if(k==r->control_count){if(k==RSS_DDC_PROFILE_MAX_CONTROLS){z=RSS_DDC_ERROR_PROFILE_CONFLICT;break;}r->controls[k]=*q;r->controls[k].source=p->source;r->controls[k].write_authorized=q->writable&&q->confidence==RSS_DDC_PROFILE_CONFIDENCE_HARDWARE_VALIDATED&&p->source!=RSS_DDC_PROFILE_SOURCE_RESEARCH;co[k]=q->confidence;so[k]=rank(p->source);sp[k]=score;++r->control_count;continue;}if((unsigned)q->confidence>co[k]||((unsigned)q->confidence==co[k]&&(rank(p->source)>so[k]||(rank(p->source)==so[k]&&score>sp[k])))){r->controls[k]=*q;r->controls[k].source=p->source;r->controls[k].write_authorized=q->writable&&q->confidence==RSS_DDC_PROFILE_CONFIDENCE_HARDWARE_VALIDATED&&p->source!=RSS_DDC_PROFILE_SOURCE_RESEARCH;co[k]=q->confidence;so[k]=rank(p->source);sp[k]=score;}else if((unsigned)q->confidence==co[k]&&rank(p->source)==so[k]&&score==sp[k]&&!equal_control(q,&r->controls[k]))z=RSS_DDC_ERROR_PROFILE_CONFLICT;}}if(!z&&!r->control_count)z=RSS_DDC_ERROR_NOT_FOUND;if(!z)*out=*r;free(r);return z;}
size_t rss_ddc_effective_profile_control_count(const RSSDDCEffectiveProfile*e){return e?e->control_count:0;} RSSDDCError rss_ddc_effective_profile_control(const RSSDDCEffectiveProfile*e,size_t i,RSSDDCProfileControl*c){if(!e||!c)return RSS_DDC_ERROR_ARGUMENT;if(i>=e->control_count)return RSS_DDC_ERROR_NOT_FOUND;*c=e->controls[i];return RSS_DDC_OK;} RSSDDCError rss_ddc_profile_control_enum_value(const RSSDDCProfileControl*c,size_t i,RSSDDCProfileEnumValue*v){if(!c||!v)return RSS_DDC_ERROR_ARGUMENT;if(i>=c->enum_value_count)return RSS_DDC_ERROR_NOT_FOUND;*v=c->enum_values[i];return RSS_DDC_OK;}
void rss_ddc_profile_identity_from_display(const RSSDDCDisplay*d,RSSDDCProfileIdentity*i){if(!i)return;*i=(RSSDDCProfileIdentity){};if(!d)return;snprintf(i->manufacturer,sizeof(i->manufacturer),"%s",d->manufacturer);snprintf(i->product_name,sizeof(i->product_name),"%s",d->product_name);snprintf(i->serial,sizeof(i->serial),"%s",d->serial);snprintf(i->branch_device_id,sizeof(i->branch_device_id),"%s",d->branch_device_id);snprintf(i->transport,sizeof(i->transport),"%s",d->transport);i->provider=d->provider;i->external=d->external;}

